  "imagemX": "https://www.vaticannews.va/content/dam/vaticannews/agenzie/images/srv/2026/05/30/2026-05-30-santo-rosario-per-la-chiusura-del-mese-mariano/1780161960642.JPG/_jcr_content/renditions/cq5dam.thumbnail.cropped.750.422.jpeg",
